export const CONTENT_REVIEWED='2026-11-14';
export function cityContent(slug){const content=CITY_CONTENT[slug];if(!content)throw Error('Missing city content: '+slug);return content;}
export function cityDescription(city){const c=cityContent(city.slug);return `Check the current time in ${city.name}, ${city.country}. Explore ${c.label}, local clock rules and time differences with related cities. Free, no account needed.`;}
